package com.mamtrex.hospital.radiology;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/radiology-orders") public class RadiologyOrderController { private final RadiologyOrderRepository repo; private final AuditService audit; public RadiologyOrderController(RadiologyOrderRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String modality, @jakarta.validation.constraints.NotBlank String bodyRegion, @jakarta.validation.constraints.NotBlank String report, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public RadiologyOrder create(@Valid @RequestBody Request r){var e=repo.save(new RadiologyOrder(r.patientId(), r.modality(), r.bodyRegion(), r.report(), r.status()));audit.record("CREATE","RadiologyOrder",e.getId().toString(),"created");return e;} @GetMapping public List<RadiologyOrder> list(){return repo.findAll();} @GetMapping("/{id}") public RadiologyOrder get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("RadiologyOrder not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("RadiologyOrder not found: "+id);repo.deleteById(id);audit.record("DELETE","RadiologyOrder",id.toString(),"deleted");} }
